import json,torch,torch.nn.functional as F
L=22
w1=W(f'model.layers.{L}.feed_forward.w1.weight'); w3=W(f'model.layers.{L}.feed_forward.w3.weight'); w2=W(f'model.layers.{L}.feed_forward.w2.weight')
def sc(seeds):
    r=F.normalize(w1[seeds].mean(0),dim=0); u=F.normalize(w3[seeds].mean(0),dim=0); c=F.normalize(w2[:,seeds].mean(1),dim=0)
    return (F.normalize(w1,dim=1)@r+F.normalize(w3,dim=1)@u)/2*0.5+0.5*(F.normalize(w2,dim=0).T@c)
